//! A table-driven LALR(1) parser that runs the parse tables of Mermaid's
//! compiled Jison grammars.
//!
//! Mermaid parses most diagram types with Jison. Running the very same tables
//! (generated by `tools/jison/gen.py` from Mermaid's bundle) reproduces its
//! grammar exactly, conflicts and error cases included. Each diagram type
//! supplies a lexer (Jison lexers are ordered regex rules with states, ported
//! by hand) and the semantic actions of its productions.

/// Parse tables of one grammar.
pub(crate) struct Tables {
    /// `actions[offsets[s]..offsets[s + 1]]` holds state `s`'s actions,
    /// sorted by symbol.
    pub offsets: &'static [u32],
    /// `(symbol, action)`: the kind in bits 16.. (0 goto, 1 shift, 2 reduce,
    /// 3 accept) and the target state or production below.
    pub actions: &'static [(u16, u32)],
    /// States that reduce without looking at the next token.
    pub defaults: &'static [(u16, u32)],
    /// `(lhs symbol, rhs length)` of each production.
    pub productions: &'static [(u16, u8)],
}

impl Tables {
    fn action(&self, state: usize, symbol: u16) -> Option<u32> {
        let row = &self.actions[self.offsets[state] as usize..self.offsets[state + 1] as usize];
        row.binary_search_by_key(&symbol, |a| a.0)
            .ok()
            .map(|i| row[i].1)
    }

    fn default(&self, state: usize) -> Option<u32> {
        self.defaults
            .binary_search_by_key(&(state as u16), |d| d.0)
            .ok()
            .map(|i| self.defaults[i].1)
    }
}

/// A token from a grammar's lexer.
pub(crate) struct Token {
    /// The grammar symbol, or `None` for a token name the grammar does not
    /// know (Jison then fails on it).
    pub symbol: Option<u16>,
    pub text: String,
    /// Char index of the token in the lexed text.
    pub pos: usize,
}

/// What a grammar supplies to the driver.
pub(crate) trait Grammar {
    type Value: Default;

    /// The next token. `Err(pos)` is a lexical error at that char index.
    fn lex(&mut self) -> Result<Token, usize>;

    /// The value a shifted token carries (`yytext`).
    fn token_value(&mut self, token: &Token) -> Self::Value;

    /// Runs production `prod`'s action on its right-hand side values and
    /// returns `$$`. When the action sets nothing, Jison's `$$` is `$1`.
    fn reduce(&mut self, prod: usize, rhs: Vec<Self::Value>) -> Result<Self::Value, String>;
}

/// Why a parse failed.
#[derive(Debug)]
pub(crate) enum Failure {
    /// Lexical error at a char index.
    Lex(usize),
    /// Unexpected token at a char index (`None` at the end of the input).
    Parse(usize, String),
    /// A semantic action failed.
    Action(String, usize),
}

/// Jison's `parse()`.
pub(crate) fn parse<G: Grammar>(t: &Tables, g: &mut G) -> Result<(), Failure> {
    let mut states: Vec<usize> = vec![0];
    let mut values: Vec<G::Value> = vec![G::Value::default()];
    let mut lookahead: Option<Token> = None;
    let mut last_pos = 0;
    loop {
        let state = *states.last().unwrap();
        let action = match t.default(state) {
            Some(a) => Some(a),
            None => {
                if lookahead.is_none() {
                    let tok = g.lex().map_err(Failure::Lex)?;
                    last_pos = tok.pos;
                    lookahead = Some(tok);
                }
                let tok = lookahead.as_ref().unwrap();
                tok.symbol.and_then(|s| t.action(state, s))
            }
        };
        let Some(action) = action else {
            let tok = lookahead.as_ref();
            return Err(Failure::Parse(
                tok.map_or(last_pos, |t| t.pos),
                tok.map(|t| t.text.clone()).unwrap_or_default(),
            ));
        };
        let (kind, arg) = (action >> 16, (action & 0xffff) as usize);
        match kind {
            1 => {
                let tok = lookahead.take().expect("shift without a token");
                values.push(g.token_value(&tok));
                states.push(arg);
            }
            2 => {
                let (lhs, len) = t.productions[arg];
                let len = len as usize;
                let rhs = values.split_off(values.len() - len);
                states.truncate(states.len() - len);
                let v = g
                    .reduce(arg, rhs)
                    .map_err(|m| Failure::Action(m, last_pos))?;
                let top = *states.last().unwrap();
                let Some(goto) = t.action(top, lhs) else {
                    return Err(Failure::Parse(last_pos, String::new()));
                };
                values.push(v);
                states.push((goto & 0xffff) as usize);
            }
            3 => return Ok(()),
            _ => return Err(Failure::Parse(last_pos, String::new())),
        }
    }
}
